    // ── Create ────────────────────────────────────────────────────────────────

    [Fact]
    public async Task CreateAsync_AdminWithUniqueName_ReturnsBoardDetailDtoWithOwnerRole()
    {
        var repo = new FakeBoardRepository(nameExists: false);
        var sut = CreateSut(boardRepo: repo);

