using System.Data;
using FluentAssertions;
using Kanban.Business.Services;
using Kanban.Business.Interfaces;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Exceptions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging.Abstractions;
using Moq;
using Xunit;
using static Kanban.Tests.Unit.Builders.BoardBuilder;
using static Kanban.Tests.Unit.Builders.LaneBuilder;

namespace Kanban.Tests.Unit.Business;

public sealed class LaneServiceTests
{
    private readonly Guid _boardId = Guid.NewGuid();
    private readonly Guid _ownerUserId = Guid.NewGuid();

    private LaneService CreateSut(
        ILaneRepository? laneRepo = null,
        IBoardRepository? boardRepo = null,
        IBoardMemberRepository? memberRepo = null,
        FakeCurrentUserService? currentUser = null,
        IAuthorizationService? authService = null)
    {
        var connection = new Microsoft.Data.Sqlite.SqliteConnection("Data Source=:memory:");
        connection.Open();
        var board = ABoard().WithId(_boardId).Build();
        return new LaneService(
            laneRepo ?? new FakeLaneRepository(),
            boardRepo ?? new FakeBoardRepository(boardForMember: board),
            memberRepo ?? new FakeBoardMemberRepository(BoardRole.Owner),
            currentUser ?? new FakeCurrentUserService(_ownerUserId, "standard"),
            authService ?? BuildSucceedingAuthService(),
            connection,
            new FakeDbConnectionFactory(),
            NullLogger<LaneService>.Instance);
    }

    private static IAuthorizationService BuildSucceedingAuthService()
    {
        var mock = new Mock<IAuthorizationService>();
        mock.Setup(s => s.AuthorizeAsync(
                It.IsAny<System.Security.Claims.ClaimsPrincipal>(),
                It.IsAny<object?>(),
                It.IsAny<string>()))
            .ReturnsAsync(AuthorizationResult.Success());
        mock.Setup(s => s.AuthorizeAsync(
                It.IsAny<System.Security.Claims.ClaimsPrincipal>(),
                It.IsAny<object?>(),
                It.IsAny<IEnumerable<IAuthorizationRequirement>>()))
            .ReturnsAsync(AuthorizationResult.Success());
        return mock.Object;
    }

    private static IAuthorizationService BuildFailingAuthService()
    {
        var mock = new Mock<IAuthorizationService>();
        mock.Setup(s => s.AuthorizeAsync(
                It.IsAny<System.Security.Claims.ClaimsPrincipal>(),
                It.IsAny<object?>(),
                It.IsAny<string>()))
            .ReturnsAsync(AuthorizationResult.Failed());
        mock.Setup(s => s.AuthorizeAsync(
                It.IsAny<System.Security.Claims.ClaimsPrincipal>(),
                It.IsAny<object?>(),
                It.IsAny<IEnumerable<IAuthorizationRequirement>>()))
            .ReturnsAsync(AuthorizationResult.Failed());
        return mock.Object;
    }

    // ── Create ────────────────────────────────────────────────────────────────

    [Fact]
    public async Task CreateAsync_UniqueName_AppendsAtPositionN1()
    {
        var laneRepo = new FakeLaneRepository(countInBoard: 2, nameExistsInBoard: false);
        var sut = CreateSut(laneRepo: laneRepo);

        var result = await sut.CreateAsync(_boardId, new CreateLaneRequest("New Lane"));

        result.Name.Should().Be("New Lane");
        result.Position.Should().Be(3);
        laneRepo.InsertedLane.Should().NotBeNull();
        laneRepo.InsertedLane!.Position.Should().Be(3);
    }

    [Fact]
    public async Task CreateAsync_DuplicateName_ThrowsConflictException()
    {
        var laneRepo = new FakeLaneRepository(nameExistsInBoard: true);
        var sut = CreateSut(laneRepo: laneRepo);

        var act = () => sut.CreateAsync(_boardId, new CreateLaneRequest("Existing Lane"));

        await act.Should().ThrowAsync<ConflictException>()
            .Where(e => e.Code == "lane.name_conflict");
    }

    [Fact]
    public async Task CreateAsync_NonExistentBoard_ThrowsNotFoundException()
    {
        var boardRepo = new FakeBoardRepository(boardForMember: null);
        var sut = CreateSut(boardRepo: boardRepo);

        var act = () => sut.CreateAsync(Guid.NewGuid(), new CreateLaneRequest("Lane"));

        await act.Should().ThrowAsync<NotFoundException>()
            .Where(e => e.Code == "board.not_found");
    }

    [Fact]
    public async Task CreateAsync_ViewerCaller_ThrowsForbiddenException()
    {
        var sut = CreateSut(authService: BuildFailingAuthService());

        var act = () => sut.CreateAsync(_boardId, new CreateLaneRequest("Lane"));

        await act.Should().ThrowAsync<ForbiddenException>();
    }

    // ── Rename ────────────────────────────────────────────────────────────────

    [Fact]
    public async Task RenameAsync_UniqueName_ReturnsUpdatedLane()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).WithName("Old Name").Build();
        var laneRepo = new FakeLaneRepository(lane: lane, nameExistsInBoard: false);
        var sut = CreateSut(laneRepo: laneRepo);

        var result = await sut.RenameAsync(_boardId, laneId, new RenameLaneRequest("New Name"));

        result.Name.Should().Be("New Name");
    }

    [Fact]
    public async Task RenameAsync_DuplicateName_ThrowsConflictException()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).Build();
        var laneRepo = new FakeLaneRepository(lane: lane, nameExistsInBoard: true);
        var sut = CreateSut(laneRepo: laneRepo);

        var act = () => sut.RenameAsync(_boardId, laneId, new RenameLaneRequest("Duplicate"));

        await act.Should().ThrowAsync<ConflictException>()
            .Where(e => e.Code == "lane.name_conflict");
    }

    // ── Delete ────────────────────────────────────────────────────────────────

    [Fact]
    public async Task DeleteAsync_ExistingLane_DeletesAndShiftsPositions()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).AtPosition(2).Build();
        var laneRepo = new FakeLaneRepository(lane: lane, countInBoard: 3);
        var sut = CreateSut(laneRepo: laneRepo);

        await sut.DeleteAsync(_boardId, laneId);

        laneRepo.DeletedLaneId.Should().Be(laneId);
        laneRepo.ShiftedFrom.Should().Be(3);
    }

    [Fact]
    public async Task DeleteAsync_PositionsGaplessAfterDelete()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).AtPosition(1).Build();
        var laneRepo = new FakeLaneRepository(lane: lane, countInBoard: 3);
        var sut = CreateSut(laneRepo: laneRepo);

        await sut.DeleteAsync(_boardId, laneId);

        laneRepo.ShiftedDelta.Should().Be(-1);
    }

    // ── Move ──────────────────────────────────────────────────────────────────

    [Fact]
    public async Task MoveAsync_ValidMove_UpdatesPositionWithVersionCheck()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).AtPosition(1).WithVersion(1).Build();
        var laneRepo = new FakeLaneRepository(lane: lane, updatePositionRows: 1);
        var sut = CreateSut(laneRepo: laneRepo);

        await sut.MoveAsync(_boardId, laneId, new MoveLaneRequest(3, 1));

        laneRepo.MovedToPosition.Should().Be(3);
    }

    [Fact]
    public async Task MoveAsync_VersionMismatch_ThrowsConflictException()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).WithVersion(5).Build();
        var laneRepo = new FakeLaneRepository(lane: lane, updatePositionRows: 0);
        var sut = CreateSut(laneRepo: laneRepo);

        var act = () => sut.MoveAsync(_boardId, laneId, new MoveLaneRequest(2, 1));

        await act.Should().ThrowAsync<ConflictException>()
            .Where(e => e.Code == "lane.version_conflict");
    }

    [Fact]
    public async Task MoveAsync_PositionsGaplessAfterReorder()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).AtPosition(3).WithVersion(1).Build();
        var laneRepo = new FakeLaneRepository(lane: lane, countInBoard: 4, updatePositionRows: 1);
        var sut = CreateSut(laneRepo: laneRepo);

        await sut.MoveAsync(_boardId, laneId, new MoveLaneRequest(1, 1));

        laneRepo.ShiftedFrom.Should().BeGreaterThan(0);
    }

    // ── Fakes ─────────────────────────────────────────────────────────────────

    private sealed class FakeLaneRepository : ILaneRepository
    {
        private readonly Lane? _lane;
        private readonly bool _nameExistsInBoard;
        private readonly int _countInBoard;
        private readonly int _updatePositionRows;

        public Lane? InsertedLane { get; private set; }
        public Guid? DeletedLaneId { get; private set; }
        public int ShiftedFrom { get; private set; }
        public int ShiftedDelta { get; private set; }
        public int MovedToPosition { get; private set; }

        public FakeLaneRepository(
            Lane? lane = null,
            bool nameExistsInBoard = false,
            int countInBoard = 0,
            int updatePositionRows = 1)
        {
            _lane = lane;
            _nameExistsInBoard = nameExistsInBoard;
            _countInBoard = countInBoard;
            _updatePositionRows = updatePositionRows;
        }

        public Task<IReadOnlyList<Lane>> FindByBoardAsync(Guid boardId, IDbTransaction? tx = null)
            => Task.FromResult<IReadOnlyList<Lane>>(_lane is not null ? [_lane] : []);

        public Task<Lane?> FindByIdAsync(Guid laneId, IDbTransaction? tx = null)
            => Task.FromResult(_lane?.Id == laneId ? _lane : null);

        public Task InsertAsync(Lane lane, IDbTransaction tx)
        {
            InsertedLane = lane;
            return Task.CompletedTask;
        }

        public Task UpdateNameAsync(Guid laneId, string name, IDbTransaction tx)
            => Task.CompletedTask;

        public Task<int> UpdatePositionAsync(Guid laneId, int newPosition, int expectedVersion, IDbTransaction tx)
            => Task.FromResult(_updatePositionRows);

        public Task SetPositionAsync(Guid laneId, int position, IDbTransaction tx)
        {
            MovedToPosition = position;
            return Task.CompletedTask;
        }

        public Task ShiftPositionsAsync(Guid boardId, int fromPosition, int toPosition, int delta, IDbTransaction tx)
        {
            ShiftedFrom = fromPosition;
            ShiftedDelta = delta;
            return Task.CompletedTask;
        }

        public Task DeleteAsync(Guid laneId, IDbTransaction tx)
        {
            DeletedLaneId = laneId;
            return Task.CompletedTask;
        }

        public Task<int> CountInBoardAsync(Guid boardId, IDbTransaction? tx = null)
            => Task.FromResult(_countInBoard);

        public Task<bool> ExistsWithNameInBoardAsync(Guid boardId, string name, IDbTransaction? tx = null)
            => Task.FromResult(_nameExistsInBoard);
    }

    private sealed class FakeBoardRepository : IBoardRepository
    {
        private readonly Board? _boardForMember;

        public FakeBoardRepository(Board? boardForMember = null) => _boardForMember = boardForMember;

        public Task<Board?> FindBoardForMemberAsync(Guid boardId, Guid userId, IDbTransaction? tx = null)
            => Task.FromResult(_boardForMember);

        public Task<IReadOnlyList<Board>> FindBoardsForUserAsync(Guid userId, IDbTransaction? tx = null)
            => Task.FromResult<IReadOnlyList<Board>>([]);

        public Task InsertAsync(Board board, IDbTransaction tx) => Task.CompletedTask;

        public Task<bool> ExistsWithNameAsync(string name, IDbTransaction? tx = null)
            => Task.FromResult(false);

        public Task DeleteAsync(Guid boardId, IDbTransaction tx) => Task.CompletedTask;
    }

    private sealed class FakeBoardMemberRepository : IBoardMemberRepository
    {
        private readonly BoardRole? _role;

        public FakeBoardMemberRepository(BoardRole? role = null) => _role = role;

        public Task<BoardRole?> FindRoleAsync(Guid boardId, Guid userId, IDbTransaction? tx = null)
            => Task.FromResult(_role);

        public Task<int> CountOwnersAsync(Guid boardId, IDbTransaction? tx = null)
            => Task.FromResult(1);

        public Task InsertAsync(BoardMember member, IDbTransaction tx) => Task.CompletedTask;
        public Task DeleteAsync(Guid boardId, Guid userId, IDbTransaction tx) => Task.CompletedTask;

        public Task UpdateRoleAsync(Guid boardId, Guid userId, BoardRole newRole, IDbTransaction tx)
            => Task.CompletedTask;

        public Task<IReadOnlyList<BoardMember>> FindAllForBoardAsync(Guid boardId, IDbTransaction? tx = null)
            => Task.FromResult<IReadOnlyList<BoardMember>>([]);
    }

    private sealed class FakeCurrentUserService : Kanban.Business.Interfaces.ICurrentUserService
    {
        public FakeCurrentUserService(Guid userId, string systemRole)
        {
            UserId = userId;
            SystemRole = systemRole;
            IsAuthenticated = true;
            IsRegistered = true;
        }

        public bool IsAuthenticated { get; }
        public bool IsRegistered { get; }
        public Guid? UserId { get; }
        public string? SystemRole { get; }
        public System.Security.Claims.ClaimsPrincipal Principal { get; } = new();
    }

    private sealed class FakeDbConnectionFactory : IDbConnectionFactory
    {
        public IDbTransaction BeginDeferredTransaction(IDbConnection connection)
            => connection.BeginTransaction();
    }
}

using System.Data;
using FluentValidation;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain.Entities;
using Kanban.Domain.Exceptions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class LaneService : ILaneService
{
    private readonly ILaneRepository _laneRepository;
    private readonly IBoardRepository _boardRepository;
    private readonly IBoardMemberRepository _boardMemberRepository;
    private readonly ICurrentUserService _currentUserService;
    private readonly IAuthorizationService _authorizationService;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<LaneService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public LaneService(
        ILaneRepository laneRepository,
        IBoardRepository boardRepository,
        IBoardMemberRepository boardMemberRepository,
        ICurrentUserService currentUserService,
        IAuthorizationService authorizationService,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<LaneService> logger)
    {
        ArgumentNullException.ThrowIfNull(laneRepository);
        ArgumentNullException.ThrowIfNull(boardRepository);
        ArgumentNullException.ThrowIfNull(boardMemberRepository);
        ArgumentNullException.ThrowIfNull(currentUserService);
        ArgumentNullException.ThrowIfNull(authorizationService);
        ArgumentNullException.ThrowIfNull(dbConnection);
        ArgumentNullException.ThrowIfNull(transactionFactory);
        ArgumentNullException.ThrowIfNull(logger);
        _laneRepository = laneRepository;
        _boardRepository = boardRepository;
        _boardMemberRepository = boardMemberRepository;
        _currentUserService = currentUserService;
        _authorizationService = authorizationService;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<LaneDto> CreateAsync(Guid boardId, CreateLaneRequest request)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<CreateLaneRequest>
            { v => v.RuleFor(x => x.Name).NotEmpty().MaximumLength(100) }
            .ValidateAndThrow(request);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal, new BoardContext(boardId), new BoardMembershipRequirement(BoardOperations.CreateLane));
        if (!auth.Succeeded)
            throw new ForbiddenException("lane.create_forbidden", "You do not have permission to create lanes on this board.");

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                if (await _laneRepository.ExistsWithNameInBoardAsync(boardId, request.Name, tx))
                    throw new ConflictException("lane.name_conflict", "A lane with this name already exists on the board.");

                var count = await _laneRepository.CountInBoardAsync(boardId, tx);
                var position = count + 1;
                var lane = new Lane(Guid.NewGuid(), boardId, request.Name, position, 1, DateTimeOffset.UtcNow);
                await _laneRepository.InsertAsync(lane, tx);

                tx.Commit();
                _logger.LogInformation("Lane {LaneId} created on board {BoardId} by user {UserId}",
                    lane.Id, boardId, userId);
                return LaneTransforms.ToDto(lane, []);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }

    public async Task<LaneDto> RenameAsync(Guid boardId, Guid laneId, RenameLaneRequest request)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }
            .ValidateAndThrow(laneId);
        new InlineValidator<RenameLaneRequest>
            { v => v.RuleFor(x => x.Name).NotEmpty().MaximumLength(100) }
            .ValidateAndThrow(request);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        var lane = await _laneRepository.FindByIdAsync(laneId)
            ?? throw new NotFoundException("lane.not_found", "Lane not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal, new BoardContext(boardId), new BoardMembershipRequirement(BoardOperations.UpdateLane));
        if (!auth.Succeeded)
            throw new ForbiddenException("lane.update_forbidden", "You do not have permission to update lanes on this board.");

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                if (await _laneRepository.ExistsWithNameInBoardAsync(boardId, request.Name, tx))
                    throw new ConflictException("lane.name_conflict", "A lane with this name already exists on the board.");

                lane.Rename(request.Name);
                await _laneRepository.UpdateNameAsync(laneId, request.Name, tx);

                tx.Commit();
                return LaneTransforms.ToDto(lane, []);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }

    public async Task MoveAsync(Guid boardId, Guid laneId, MoveLaneRequest request)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }
            .ValidateAndThrow(laneId);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        var lane = await _laneRepository.FindByIdAsync(laneId)
            ?? throw new NotFoundException("lane.not_found", "Lane not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal, new BoardContext(boardId), new BoardMembershipRequirement(BoardOperations.UpdateLane));
        if (!auth.Succeeded)
            throw new ForbiddenException("lane.update_forbidden", "You do not have permission to update lanes on this board.");

        var oldPosition = lane.Position;
        var newPosition = request.TargetPosition;

        await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var rowsAffected = await _laneRepository.UpdatePositionAsync(laneId, 0, request.ExpectedVersion, tx);
                if (rowsAffected == 0)
                    throw new ConflictException("lane.version_conflict", "The lane was modified by another user. Please refresh and try again.");

                if (newPosition < oldPosition)
                    await _laneRepository.ShiftPositionsAsync(boardId, newPosition, oldPosition - 1, 1, tx);
                else if (newPosition > oldPosition)
                    await _laneRepository.ShiftPositionsAsync(boardId, oldPosition + 1, newPosition, -1, tx);

                await _laneRepository.SetPositionAsync(laneId, newPosition, tx);

                tx.Commit();
                _logger.LogInformation("Lane {LaneId} moved to position {Position} on board {BoardId} by user {UserId}",
                    laneId, newPosition, boardId, userId);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }

    public async Task DeleteAsync(Guid boardId, Guid laneId)
    {
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }
            .ValidateAndThrow(boardId);
        new InlineValidator<Guid>
            { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }
            .ValidateAndThrow(laneId);

        var userId = _currentUserService.UserId!.Value;
        _ = await _boardRepository.FindBoardForMemberAsync(boardId, userId)
            ?? throw new NotFoundException("board.not_found", "Board not found.");

        var lane = await _laneRepository.FindByIdAsync(laneId)
            ?? throw new NotFoundException("lane.not_found", "Lane not found.");

        var auth = await _authorizationService.AuthorizeAsync(
            _currentUserService.Principal, new BoardContext(boardId), new BoardMembershipRequirement(BoardOperations.DeleteLane));
        if (!auth.Succeeded)
            throw new ForbiddenException("lane.delete_forbidden", "You do not have permission to delete lanes on this board.");

        var deletedPosition = lane.Position;

        await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                await _laneRepository.DeleteAsync(laneId, tx);
                await _laneRepository.ShiftPositionsAsync(boardId, deletedPosition + 1, int.MaxValue, -1, tx);

                tx.Commit();
                _logger.LogInformation("Lane {LaneId} deleted from board {BoardId} by user {UserId}",
                    laneId, boardId, userId);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        });
    }
}

using System.Data;
using Dapper;
using FluentValidation;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;

namespace Kanban.DataAccess.Repositories;

public sealed class LaneRepository : ILaneRepository
{
    private readonly IDbConnection _connection;

    public LaneRepository(IDbConnection connection)
    {
        ArgumentNullException.ThrowIfNull(connection);
        _connection = connection;
    }

    public async Task<IReadOnlyList<Lane>> FindByBoardAsync(Guid boardId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }.ValidateAndThrow(boardId);

        const string sql = """
            SELECT id, board_id AS BoardId, name, position, version, created_at AS CreatedAt
            FROM lanes
            WHERE board_id = @boardId
            ORDER BY position ASC
            """;

        var results = await _connection.QueryAsync<Lane>(
            sql, new { boardId = boardId.ToString("D") }, transaction: tx);
        return results.AsList();
    }

    public async Task<Lane?> FindByIdAsync(Guid laneId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);

        const string sql = """
            SELECT id, board_id AS BoardId, name, position, version, created_at AS CreatedAt
            FROM lanes
            WHERE id = @laneId
            """;

        return await _connection.QuerySingleOrDefaultAsync<Lane>(
            sql, new { laneId = laneId.ToString("D") }, transaction: tx);
    }

    public async Task InsertAsync(Lane lane, IDbTransaction tx)
    {
        ArgumentNullException.ThrowIfNull(lane);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            INSERT INTO lanes (id, board_id, name, position, version, created_at)
            VALUES (@id, @boardId, @name, @position, @version, @createdAt)
            """;

        await _connection.ExecuteAsync(sql, new
        {
            id = lane.Id.ToString("D"),
            boardId = lane.BoardId.ToString("D"),
            name = lane.Name,
            position = lane.Position,
            version = lane.Version,
            createdAt = lane.CreatedAt.ToString("o"),
        }, transaction: tx);
    }

    public async Task UpdateNameAsync(Guid laneId, string name, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("name") }.ValidateAndThrow(name);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = "UPDATE lanes SET name = @name WHERE id = @laneId";
        await _connection.ExecuteAsync(sql,
            new { laneId = laneId.ToString("D"), name }, transaction: tx);
    }

    public async Task<int> UpdatePositionAsync(Guid laneId, int newPosition, int expectedVersion, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            UPDATE lanes
            SET position = @newPosition, version = version + 1
            WHERE id = @laneId
              AND version = @expectedVersion
            """;

        return await _connection.ExecuteAsync(sql, new
        {
            laneId = laneId.ToString("D"),
            newPosition,
            expectedVersion,
        }, transaction: tx);
    }

    public async Task SetPositionAsync(Guid laneId, int position, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = "UPDATE lanes SET position = @position WHERE id = @laneId";
        await _connection.ExecuteAsync(sql, new { laneId = laneId.ToString("D"), position }, transaction: tx);
    }

    public async Task ShiftPositionsAsync(Guid boardId, int fromPosition, int toPosition, int delta, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }.ValidateAndThrow(boardId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = """
            UPDATE lanes
            SET position = position + @delta
            WHERE board_id = @boardId
              AND position >= @fromPosition
              AND position <= @toPosition
            """;

        await _connection.ExecuteAsync(sql, new
        {
            boardId = boardId.ToString("D"),
            fromPosition,
            toPosition,
            delta,
        }, transaction: tx);
    }

    public async Task DeleteAsync(Guid laneId, IDbTransaction tx)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("laneId") }.ValidateAndThrow(laneId);
        ArgumentNullException.ThrowIfNull(tx);

        const string sql = "DELETE FROM lanes WHERE id = @laneId";
        await _connection.ExecuteAsync(sql,
            new { laneId = laneId.ToString("D") }, transaction: tx);
    }

    public async Task<int> CountInBoardAsync(Guid boardId, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }.ValidateAndThrow(boardId);

        const string sql = "SELECT COUNT(*) FROM lanes WHERE board_id = @boardId";
        return await _connection.QuerySingleAsync<int>(
            sql, new { boardId = boardId.ToString("D") }, transaction: tx);
    }

    public async Task<bool> ExistsWithNameInBoardAsync(Guid boardId, string name, IDbTransaction? tx = null)
    {
        new InlineValidator<Guid> { v => v.RuleFor(x => x).NotEqual(Guid.Empty).WithName("boardId") }.ValidateAndThrow(boardId);
        new InlineValidator<string> { v => v.RuleFor(x => x).NotEmpty().WithName("name") }.ValidateAndThrow(name);

        const string sql = "SELECT COUNT(*) FROM lanes WHERE board_id = @boardId AND name = @name COLLATE NOCASE";
        var count = await _connection.QuerySingleAsync<int>(
            sql, new { boardId = boardId.ToString("D"), name }, transaction: tx);
        return count > 0;
    }
}

